// AiXenix Cosmos Lab: navigation bounds for galaxies, regions (groups, clusters, sky/navigation regions) and the whole
// catalogue. Pure and read-only: it uses the c1 model as published and changes nothing about it (no generator, count,
// position or system effect). A region is a navigation unit; grouping galaxies here asserts nothing about whether they
// are gravitationally bound (that is content's per-region metadata).
//
// Safety: every bound encloses the full model extent of each member galaxy (all components, halo included, offsets
// included), so a camera framed on it shows every model star a sample of those galaxies can contain.
// A bound's radius is a CAMERA extent (what to frame), never a virial, tidal or gravitational boundary. Empty or unknown
// member lists give null, never NaN. fitDistance frames the sphere's angular radius (asin) within the narrower of the
// horizontal and vertical half fields of view, so a portrait phone (e.g. 390 px wide) does not clip it.

import { galaxyState } from './galaxy';
import type { Universe, Vec3 } from './types';

export interface Sphere {
  centrePc: Vec3;
  radiusPc: number;
}

export interface Bounds extends Sphere {
  /** Axis-aligned box of the member spheres (universe frame, pc). */
  min: Vec3;
  max: Vec3;
  /** Galaxy ids enclosed. */
  members: string[];
  /** Requested ids that are not galaxies of this universe (excluded from the bounds). */
  missing: string[];
}

/** 'model': every component incl. halo (what samples can contain); 'disk': the galaxy's nominal radius (summary.radiusPc). */
export type ExtentMode = 'model' | 'disk';

export interface BoundsOptions {
  mode?: ExtentMode;
  /** Extra margin as a fraction of the radius (default 0). */
  padding?: number;
  /** Lower limit of the radius (pc, default 0). */
  minRadiusPc?: number;
}

/** Minimal region shape the helpers need (content's region records are a superset). */
export interface RegionInput {
  id: string;
  /** Galaxy ids that belong to this region directly. */
  members: string[];
  /** Enclosing region id (null/absent for a top-level region). */
  parent?: string | null;
}

export interface RegionBounds extends Bounds {
  regionId: string;
  /** Members including every descendant region's members (sorted, unique). */
  allMembers: string[];
}

export interface RegionIssue {
  regionId: string;
  problem: 'duplicate_id' | 'unknown_parent' | 'cycle' | 'unknown_member' | 'empty';
  detail: string;
}

function finiteVec(v: unknown): v is Vec3 {
  return Array.isArray(v) && v.length === 3 && v.every((x) => typeof x === 'number' && Number.isFinite(x));
}

function dist(a: Vec3, b: Vec3): number {
  return Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
}

/** Radius (pc) around the galaxy centre that contains its model (mode 'model') or its nominal disk (mode 'disk'). */
export function galaxyExtentPc(u: Universe, galaxyId: string, mode: ExtentMode = 'model'): number | null {
  const g = galaxyState(u, galaxyId);
  if (!g) return null;
  if (mode === 'disk') return g.summary.radiusPc;
  let r = g.summary.radiusPc;
  for (const c of g.comps) r = Math.max(r, c.geom.extentPc);
  return r;
}

export function galaxySphere(u: Universe, galaxyId: string, mode: ExtentMode = 'model'): Sphere | null {
  const g = galaxyState(u, galaxyId);
  const r = galaxyExtentPc(u, galaxyId, mode);
  if (!g || r === null || !finiteVec(g.centre) || !Number.isFinite(r)) return null;
  return { centrePc: [...g.centre] as Vec3, radiusPc: r };
}

/**
 * A sphere enclosing every input sphere. The radius is computed exactly from the chosen centre (then padded by a few
 * ulps), so containment is guaranteed; the centre is the better of the box centre and a Bădoiu–Clarkson iteration.
 */
export function enclosingSphere(spheres: Sphere[]): Sphere | null {
  const ok = spheres.filter((s) => s && finiteVec(s.centrePc) && Number.isFinite(s.radiusPc) && s.radiusPc >= 0);
  if (ok.length === 0) return null;
  const radiusFor = (c: Vec3) => {
    let r = 0;
    for (const s of ok) r = Math.max(r, dist(c, s.centrePc) + s.radiusPc);
    return r;
  };
  const lo: Vec3 = [Infinity, Infinity, Infinity];
  const hi: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const s of ok)
    for (let k = 0; k < 3; k++) {
      lo[k] = Math.min(lo[k]!, s.centrePc[k]! - s.radiusPc);
      hi[k] = Math.max(hi[k]!, s.centrePc[k]! + s.radiusPc);
    }
  let best: Vec3 = [(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, (lo[2] + hi[2]) / 2];
  let bestR = radiusFor(best);
  let c: Vec3 = [...best] as Vec3;
  for (let k = 1; k <= 400 && ok.length > 1; k++) {
    // Farthest point of the farthest sphere from c.
    let far = ok[0]!;
    let farD = -1;
    for (const s of ok) {
      const d = dist(c, s.centrePc) + s.radiusPc;
      if (d > farD) {
        farD = d;
        far = s;
      }
    }
    const dc = dist(c, far.centrePc);
    const dir: Vec3 = dc > 0 ? [(far.centrePc[0] - c[0]) / dc, (far.centrePc[1] - c[1]) / dc, (far.centrePc[2] - c[2]) / dc] : [0, 0, 0];
    const p: Vec3 = [far.centrePc[0] + dir[0] * far.radiusPc, far.centrePc[1] + dir[1] * far.radiusPc, far.centrePc[2] + dir[2] * far.radiusPc];
    c = [c[0] + (p[0] - c[0]) / (k + 1), c[1] + (p[1] - c[1]) / (k + 1), c[2] + (p[2] - c[2]) / (k + 1)];
    const r = radiusFor(c);
    if (r < bestR) {
      bestR = r;
      best = [...c] as Vec3;
    }
  }
  return { centrePc: best, radiusPc: bestR * (1 + 1e-12) + 1e-9 };
}

function boundsOf(u: Universe, ids: string[], opts: BoundsOptions): Bounds | null {
  const mode = opts.mode ?? 'model';
  const members: string[] = [];
  const missing: string[] = [];
  const spheres: Sphere[] = [];
  for (const id of [...new Set(ids)]) {
    const s = galaxySphere(u, id, mode);
    if (s) {
      members.push(id);
      spheres.push(s);
    } else missing.push(id);
  }
  const e = enclosingSphere(spheres);
  if (!e) return null;
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (const s of spheres)
    for (let k = 0; k < 3; k++) {
      min[k] = Math.min(min[k]!, s.centrePc[k]! - s.radiusPc);
      max[k] = Math.max(max[k]!, s.centrePc[k]! + s.radiusPc);
    }
  const pad = Number.isFinite(opts.padding) && opts.padding! > 0 ? opts.padding! : 0;
  const minR = Number.isFinite(opts.minRadiusPc) && opts.minRadiusPc! > 0 ? opts.minRadiusPc! : 0;
  return { centrePc: e.centrePc, radiusPc: Math.max(minR, e.radiusPc * (1 + pad)), min, max, members: members.sort(), missing: missing.sort() };
}

/** Bounds of a set of galaxies (unknown ids are reported in `missing`); null when none is known. Finite and > 0 for one galaxy. */
export function regionBounds(u: Universe, galaxyIds: string[], opts: BoundsOptions = {}): Bounds | null {
  return boundsOf(u, galaxyIds, opts);
}

/** Bounds of every galaxy of the universe; null for a universe without galaxies (callers must guard empty data). */
export function catalogueBounds(u: Universe, opts: BoundsOptions = {}): Bounds | null {
  return boundsOf(
    u,
    u.galaxies.map((g) => g.id),
    opts,
  );
}

/** Validates a region list against the universe: duplicates, unknown parents/members, cycles, empty regions. */
export function checkRegions(u: Universe, regions: RegionInput[]): RegionIssue[] {
  const issues: RegionIssue[] = [];
  const byId = new Map<string, RegionInput>();
  for (const r of regions) {
    if (byId.has(r.id)) issues.push({ regionId: r.id, problem: 'duplicate_id', detail: r.id });
    else byId.set(r.id, r);
  }
  const known = new Set(u.galaxies.map((g) => g.id));
  for (const r of byId.values()) {
    if (r.parent && !byId.has(r.parent)) issues.push({ regionId: r.id, problem: 'unknown_parent', detail: r.parent });
    for (const m of r.members ?? []) if (!known.has(m)) issues.push({ regionId: r.id, problem: 'unknown_member', detail: m });
    const seen = new Set<string>([r.id]);
    let p = r.parent;
    while (p && byId.has(p)) {
      if (seen.has(p)) {
        issues.push({ regionId: r.id, problem: 'cycle', detail: [...seen, p].join(' > ') });
        break;
      }
      seen.add(p);
      p = byId.get(p)!.parent;
    }
  }
  for (const r of byId.values()) if (allMembersOf(r.id, byId).length === 0) issues.push({ regionId: r.id, problem: 'empty', detail: 'no members, no member sub-regions' });
  return issues;
}

function allMembersOf(id: string, byId: Map<string, RegionInput>, guard = new Set<string>()): string[] {
  if (guard.has(id)) return [];
  guard.add(id);
  const r = byId.get(id);
  if (!r) return [];
  const out = new Set(r.members ?? []);
  for (const child of byId.values()) if (child.parent === id) for (const m of allMembersOf(child.id, byId, guard)) out.add(m);
  return [...out].sort();
}

/** Bounds of every region (its own members plus every descendant region's members). Regions without known members are omitted. */
export function boundsOfRegions(u: Universe, regions: RegionInput[], opts: BoundsOptions = {}): Map<string, RegionBounds> {
  const byId = new Map<string, RegionInput>();
  for (const r of regions) if (!byId.has(r.id)) byId.set(r.id, r);
  const out = new Map<string, RegionBounds>();
  for (const r of byId.values()) {
    const all = allMembersOf(r.id, byId);
    const b = boundsOf(u, all, opts);
    if (b) out.set(r.id, { ...b, regionId: r.id, allMembers: all });
  }
  return out;
}

/**
 * Camera distance from a sphere's centre at which the whole sphere fits a perspective view (vertical field of view in
 * degrees, aspect = width / height), times `margin` (default 1.15). Uses the narrower of the two view angles.
 */
export function fitDistance(sphere: Sphere, fovYDeg: number, aspect: number, margin = 1.15): number {
  const fy = Math.min(179, Math.max(1, Number.isFinite(fovYDeg) ? fovYDeg : 50)) * (Math.PI / 180);
  const a = Number.isFinite(aspect) && aspect > 0 ? aspect : 1;
  const fx = 2 * Math.atan(Math.tan(fy / 2) * a);
  const half = Math.min(fy, fx) / 2;
  const m = Number.isFinite(margin) && margin >= 1 ? margin : 1.15;
  return (sphere.radiusPc / Math.sin(half)) * m;
}
